def priority_v2(SH, EMP, AVG, CUR, RI, DIFF):  
    priority = (RI * 0.8) - (EMP * 0.2) - (SH * 0.05) - (DIFF * 0.02) - (AVG * 0.01)  
    return priority

def priority_v2(SH, EMP, AVG, CUR, RI, DIFF):
    if EMP == 0:
        return float('inf')
    free_space = EMP
    alignment = 1 / (1 + abs(DIFF))
    blocking_penalty = RI
    priority = 0.3 * (1 / (1 + abs(free_space - 10))) + 0.4 * (1 - alignment) + 0.3 * blocking_penalty
    return priority

def priority_v2(SH, EMP, AVG, CUR, RI, DIFF):
    priority = 0
    # Stronger penalty for blocking containers relative to free space
    if EMP > 0:
        priority += (RI / EMP) * 3.0
    # Less emphasis on stack height
    if SH > 0:
        priority += (SH * (1 + (SH - 1) * 0.01)) * 0.02
    # Reward free space with lower weight
    if EMP > 0:
        priority += (EMP * (1 + (EMP - 1) * 0.01)) * 0.1
    # Minimal reward for stacks where the smallest ID is significantly smaller
    if DIFF < 0:
        priority += abs(DIFF) * 0.05
    # Less emphasis on average ID
    if AVG > 0:
        priority += ((AVG - CUR) / (AVG + 1)) * 0.1
    return priority

def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Prioritize stacks that are expected to be retrieval-ready based on current and future needs
    if AVG == 0:
        predictive_readiness = 1.0
    else:
        if CUR == 0:
            predictive_readiness = 0.0
        else:
            predictive_readiness = (AVG - CUR) / (CUR + 1) if AVG > CUR else 0.0

    # Encourage stacks that are coherent with the current container
    if AVG == 0:
        coherence_bonus = 1.0
    else:
        if CUR == 0:
            coherence_bonus = 0.0
        else:
            coherence_bonus = (AVG - CUR) / (AVG + 1) if AVG > CUR else 0.0

    # Blockage factor: fewer containers with smaller IDs mean less blocking
    blockage_factor = (RI + 1)

    # Encourage free space: stacks with more available slots are better
    space_factor = 1 / (EMP + 1)

    # Stacks with lower average IDs are more retrieval-ready if they are known
    if CUR == 0:
        stability_factor = 0.0
    else:
        stability_factor = AVG / (CUR + 1)

    # Urgency: prioritize stacks where current container can be placed without blocking
    if AVG == 0:
        urgency_factor = 1.0
    else:
        urgency_factor = (CUR / AVG) * (RI + 1)

    # Readiness: smaller stacks with lower average IDs have better potential
    readiness = (1 / (SH + 1)) * (1 / (AVG + 1)) if AVG != 0 else 0.0

    # Future blockage estimation based on unknowns
    if CUR == 0:
        future_blockage = 0.0
    else:
        if AVG == 0:
            future_blockage = 1.0
        else:
            future_blockage = max(0, (CUR - AVG) / (CUR + 1)) * 0.5

    # Adaptive coherence: stacks with average close to current container are more future-ready
    if CUR == 0:
        adaptive_coherence = 0.0
    elif AVG == 0:
        adaptive_coherence = 1.0
    else:
        adaptive_coherence = max(0, (AVG - CUR) / (AVG + 1)) * 0.6

    # Combine all contributions with systematic weights, introducing a small deterministic differentiator
    priority = (
        (blockage_factor * space_factor) +
        (stability_factor * 0.2) +
        (urgency_factor * 0.25) +
        (EMP * 0.05) +
        (coherence_bonus * 0.15) +
        (readiness * 0.1) +
        (future_blockage * 0.15) +
        (predictive_readiness * 0.1) +
        (adaptive_coherence * 0.1) +
        (AVG * 0.001)  # Introduce a small deterministic differentiator
    )
    return priority
